INSERT INTO public.announcements (id, title, content, author, date, created_at)
VALUES
  ('anc-1', '🚀 ยินดีต้อนรับสู่ศูนย์เรียนรู้วิทยาการคำนวณ ม.4 (Full-Stack Next-Gen)', 'เรียนรู้ผ่านสื่อมัลติมีเดีย บทเรียน วิดีโอสอน สไลด์พรีเซนเตชัน E-Book หนังสือเรียน แบบทดสอบย่อย และข้อสอบกลางภาค/ปลายภาค พร้อมซิงค์ Google Sheet เรียลไทม์!', 'ครูปณิฏฐา บุญยงค์', '2026-09-18', '2026-10-26T07:46:14.791Z'),
  ('anc-2', '📌 กำหนดการสอบกลางภาคและยื่นเค้าโครงโครงงาน 5 บท', 'ให้นักเรียน ม.4 ทำแบบทดสอบกลางภาค และยื่นเค้าโครงโครงงาน 5 บทผ่านเมนู "ส่งงาน" ภายในวันที่ 15 ตุลาคม 2026', 'ครูปณิฏฐา บุญยงค์', '2026-09-18', '2026-10-26T07:46:14.792Z')
INSERT INTO public.questions (id, student_id, student_name, subject, question, reply, replied_by, status, created_at)
VALUES
  ('q-1', 'u-student1', 'นายณัฐวุฒิ เรียนดี', 'สอบถามเรื่องการเขียนผังงานในบทที่ 3 ครับ', 'ในกรณีที่มีเงื่อนไขตรวจสอบหลายชั้น ควรใช้ Decision ซ้อนกัน หรือแยกเป็นฟังก์ชันย่อยครับครู?', 'สวัสดีณัฐวุฒิ หากเงื่อนไขซับซ้อน แนะนำให้ใช้ Abstraction โดยสร้างเป็น Subroutine/ฟังก์ชันย่อย จะทำให้ผังงานหลักอ่านเข้าใจง่ายและเป็นระเบียบตามมาตรฐานครับ', 'ครูปณิฏฐา บุญยงค์', 'replied', '2026-09-17T14:20:00.000Z'),
  ('q-1789712286953', 'u-student1', 'นายณัฐวุฒิ เรียนดี', 'โครงงานระบบจองคิว', 'ขอคำปรึกษาการออกแบบ SDLC ครับ', 'ครูแนะนำให้นำเครื่องมือ SDLC Calculator ในระบบมาใช้วางแผนได้เลยครับ', 'ครูปณิฏฐา บุญยงค์', 'replied', '2026-09-18T06:18:06.953Z')
